suppressMessages({library(dplyr);library(tidyr)})
setwd("/Users/hanno/Documents/GitHub/german_election_data")
S<-"/private/tmp/claude-501/-Users-hanno-Documents-GitHub-german-election-data/adfc9cc1-5d71-47c2-9e9e-f58b91334ee3/scratchpad/audit/state-hist"
x<-readRDS("data/state_elections/final/state_unharm.rds")
b<-readRDS(file.path(S,"bl_wide.rds"))
map<-c(BW="08",BY="09",BE="11",BB="12",HB="04",HH="02",HE="06",MV="13",NI="03",NW="05",RP="07",SL="10",SN="14",ST="15",SH="01",TH="16")
b$state<-map[b$land]
g<-x|>group_by(state,election_date,election_year)|>summarise(n=n(),elig=sum(eligible_voters,na.rm=TRUE),elig_na=sum(is.na(eligible_voters)),voters=sum(number_voters,na.rm=TRUE),valid=sum(valid_votes,na.rm=TRUE),invalid=sum(invalid_votes,na.rm=TRUE),.groups="drop")
b2<-b|>transmute(state,election_date=date,bl_elig=elig,bl_voters=voters,bl_valid=valid,bl_inv=invalid,bem)
# join by state & year (date may differ)
g$yr<-g$election_year; b2$yr<-as.integer(format(b2$election_date,"%Y"))
m<-full_join(g,b2,by=c("state","yr"),suffix=c("",".bl"))
m<-m|>mutate(d_elig=100*(elig/bl_elig-1),d_voters=100*(voters/bl_voters-1),d_valid=100*(valid/bl_valid-1),turn_g=voters/elig,turn_bl=bl_voters/bl_elig,d_turn_pp=100*(turn_g-turn_bl),date_diff=as.integer(election_date-election_date.bl))
write.csv(m,file.path(S,"totals_compare.csv"),row.names=FALSE)
cat("GERDA elections not in BL (state,yr):\n");print(m|>filter(is.na(bl_valid),!is.na(n))|>select(state,yr,n,elig,valid)|>as.data.frame())
cat("BL elections not in GERDA:\n");print(m|>filter(is.na(n))|>select(state,yr,election_date.bl,bl_elig,bl_valid)|>arrange(state,yr)|>as.data.frame())
cat("Date mismatches:\n");print(m|>filter(!is.na(date_diff),date_diff!=0)|>select(state,yr,election_date,election_date.bl,date_diff)|>as.data.frame())
cat("Total deviations (|d|>1% or turnout >1pp):\n")
print(m|>filter(!is.na(bl_valid),!is.na(n),(abs(d_elig)>1|abs(d_voters)>1|abs(d_valid)>1|abs(d_turn_pp)>1))|>select(state,yr,n,elig_na,d_elig,d_voters,d_valid,d_turn_pp,turn_g,turn_bl)|>mutate(across(where(is.numeric),~round(.,2)))|>as.data.frame())
cat("Small deviations 0.1-1%:\n")
print(m|>filter(!is.na(bl_valid),!is.na(n),(abs(d_valid)>0.1&abs(d_valid)<=1)|(abs(d_elig)>0.1&abs(d_elig)<=1))|>select(state,yr,d_elig,d_voters,d_valid,d_turn_pp)|>mutate(across(where(is.numeric),~round(.,2)))|>as.data.frame())
